GUIDES = []

# ============================================================== head
GUIDES.append(dict(
    name="head", section="1", one_line="output the first part of files",
    plain=["`head` prints the beginning of a file: by default the first 10 lines. It lets you peek at a big file without opening all of it.",
           "In security work it is the quickest look at a log, a CSV, a wordlist or the first bytes of a binary."],
    when=["See what a big log or data file looks like.", "Keep only the top results of a ranked list (sort | uniq -c | sort -rn | head).", "Cut a file to its first N bytes, for example to test a header."],
    examples=[("First 10 lines", "head access.log", "With no option you get the first ten lines. Handy to learn the layout of a log before you search it."),
              ("A chosen number of lines  (-n)", "head -n 3 users.txt", "Prints the first three lines. head -3 is a short way to write the same thing."),
              ("All but the last 2 lines  (-n -2)", "head -n -2 users.txt", "A negative number means 'everything except the last N lines'. Useful for dropping a footer."),
              ("The first bytes of a file  (-c)", "head -c 16 pic.png | xxd", "-c counts bytes, not lines. Together with xxd you see the magic number of a file without reading all of it."),
              ("Top of a ranked list", "awk '{print $1}' access.log | sort | uniq -c | sort -rn | head -3", "The classic counting pipeline ends with head to keep only the three busiest IPs."),
              ("Several files at once", "head -n 2 users.txt notes.txt", "When you give several files head prints a header line with each file's name. -q hides the headers and -v forces them even for one file.")],
    options=[("-c, --bytes=[-]NUM", "Print the first NUM bytes. With a minus sign, print everything except the last NUM bytes.", "Reading a file header or trimming bytes."),
             ("-n, --lines=[-]NUM", "Print the first NUM lines (default 10). With a minus sign, everything except the last NUM lines.", "Almost every use."),
             ("-q, --quiet, --silent", "Never print the file-name headers when you give several files.", "You want one clean stream of text."),
             ("-v, --verbose", "Always print the file-name header, even for a single file.", "Labelling output in scripts."),
             ("-z, --zero-terminated", "Treat NUL bytes, not newlines, as the end of a line.", "Output of find -print0."),
             ("--help", "Print a short usage message and exit.", "A quick reminder."),
             ("--version", "Print the version and exit.", "Checking which head you have.")],
    mistakes=["head -n 1 file only reads the start; it does not tell you the file has more lines.", "On a binary file the output can garble your terminal: use head -c N file | xxd instead.", "A size suffix works (head -c 1K) but means 1024 bytes, while 1KB means 1000."],
    try_=["Show the first line of every .txt file in a folder, with names.", "Print the header row of a CSV.", "Cut a file in half by line count with wc -l and head."],
    see_also="tail(1), less(1), cat(1), sed(1) (sed -n '1,5p'), awk(1), xxd(1)."))

# ============================================================== tail
GUIDES.append(dict(
    name="tail", section="1", one_line="output the last part of files",
    plain=["`tail` prints the end of a file: by default the last 10 lines. With -f it keeps the file open and prints new lines as they are added, which is how you watch a log in real time.",
           "In incident response and defence challenges, tail -f is how you watch what an attacker is doing right now."],
    when=["See the newest log lines.", "Watch a log live while you test a service or while an attack runs.", "Skip a header: print from line 2 on."],
    examples=[("Last 10 lines", "tail access.log", "The newest entries of a log are at the bottom, so the end is usually the most interesting part."),
              ("A chosen number of lines  (-n)", "tail -n 3 users.txt", "Prints the last three lines."),
              ("Start from a line number  (-n +N)", "tail -n +2 users.txt", "A plus sign means 'start at line N and print the rest'. -n +2 skips a header row."),
              ("Follow a log as it grows  (-f)", "tail -f /var/log/auth.log", "Prints new lines as they appear, until you press Ctrl-C. Run it in a spare terminal while you try a login or send a request."),
              ("Follow and filter", "tail -f access.log | grep --line-buffered ' 401 '", "Shows only failed logins as they happen. --line-buffered stops grep from holding output back."),
              ("Follow a file that gets replaced  (-F)", "tail -F app.log", "-F re-opens the file when log rotation replaces it, and keeps waiting if it does not exist yet. Use it for long watches."),
              ("The last bytes  (-c)", "tail -c 40 pic.png | xxd", "Look at the end of a binary: data hidden after an image's end marker shows up here.")],
    options=[("-c, --bytes=[+]NUM", "Print the last NUM bytes; with a plus sign, start at byte NUM.", "Inspecting the end of a binary or an appended payload."),
             ("-n, --lines=[+]NUM", "Print the last NUM lines (default 10); with a plus sign, start at line NUM.", "Most uses."),
             ("-f, --follow[={name|descriptor}]", "Keep reading and print new data as the file grows. The default follows the open file even if it is renamed.", "Watching a live log."),
             ("-F", "Same as --follow=name --retry: follow the file by name and keep trying if it disappears or is rotated.", "Logs that are rotated."),
             ("--retry", "Keep trying to open a file that is not accessible yet.", "Following a file that will be created later."),
             ("--pid=PID", "With -f, stop when the process with this id ends.", "Watching a program's log only while it runs."),
             ("-s, --sleep-interval=N", "With -f, wait about N seconds between checks.", "Reducing load on a slow disk."),
             ("--max-unchanged-stats=N", "With --follow=name, re-open the file after N checks without change.", "Detecting a replaced file quickly."),
             ("-q, --quiet, --silent", "Never print file-name headers.", "One clean stream."),
             ("-v, --verbose", "Always print the file-name header.", "Labelled output."),
             ("-z, --zero-terminated", "Lines end with a NUL byte instead of a newline.", "Output of find -print0."),
             ("--help", "Print a short usage message.", "A quick reminder."),
             ("--version", "Print the version.", "Checking which tail you have.")],
    mistakes=["Using tail -f on a file that is rotated: you stop receiving data; use -F.", "Piping tail -f into another command that buffers (grep, awk): use --line-buffered or stdbuf.", "Forgetting Ctrl-C ends -f.", "tail -n 5 file is the last five lines; tail -n +5 file starts at line 5."],
    try_=["Watch auth.log in one terminal and trigger a failed ssh login in another.", "Print a CSV without its header row.", "Follow two logs at once with tail -f a b.", "Use tail -c 100 to find data appended after the end of an image."],
    see_also="head(1), less(1) (press F inside less to follow), journalctl -f, multitail, grep(1), watch(1)."))

# ============================================================== wc
