# ============================================================== tr
GUIDES.append(dict(
    name="tr", section="1", one_line="translate or delete characters",
    plain=["`tr` changes characters in text that you pipe into it: swap one set of characters for another, delete characters, or squeeze repeats into one.",
           "It is the one-line answer to ROT13 and Caesar shifts, upper/lower case conversion, and cleaning up line endings."],
    when=["Decode ROT13 or a Caesar shift.", "Convert upper case to lower case.", "Delete Windows carriage returns or squeeze runs of spaces."],
    examples=[("ROT13", "echo 'synt{ebg13}' | tr 'A-Za-z' 'N-ZA-Mn-za-m'", "Each letter of the first set is replaced by the letter in the same position of the second set. Shifting by 13 twice returns the original, so the same command encodes and decodes."),
              ("Upper case to lower case", "echo 'HELLO' | tr 'A-Z' 'a-z'", "Ranges such as A-Z are allowed. [:upper:] and [:lower:] also work: tr '[:upper:]' '[:lower:]'."),
              ("Delete characters  (-d)", "printf 'a\\r\\nb\\r\\n' | tr -d '\\r'", "Removes every carriage return, turning Windows line endings into Unix ones."),
              ("Squeeze repeats  (-s)", "echo 'a    b     c' | tr -s ' '", "Replaces each run of spaces by one space. Good before cut -d' '."),
              ("Keep only what you choose  (-cd)", "echo 'abc123!@#' | tr -cd '[:alnum:]'; echo", "-c means 'the complement' (everything not in the set) and -d deletes it, so only letters and digits remain."),
              ("Lines to spaces", "printf 'one\\ntwo\\nthree\\n' | tr '\\n' ' '; echo", "Joins lines into one by turning newlines into spaces."),
              ("A Caesar shift of 3", "echo 'khoor' | tr 'd-za-c' 'a-z'", "Maps each letter back three places: d to a, e to b, ... a to x. A general shift needs the two sets rotated by the shift amount.")],
    options=[("-c, -C, --complement", "Use the complement of the first set: every character not listed.", "Keep or delete 'everything except these'."),
             ("-d, --delete", "Delete the characters in the first set instead of translating.", "Stripping characters."),
             ("-s, --squeeze-repeats", "Replace each run of a repeated character from the last set by one occurrence.", "Collapsing spaces or newlines."),
             ("-t, --truncate-set1", "First cut the first set down to the length of the second set.", "Translating when the sets are different lengths."),
             ("--help", "Print a short usage message.", "A quick reminder."),
             ("--version", "Print the version.", "Checking which tr you have.")],
    mistakes=["tr reads standard input only: tr a b file does not work; use tr a b < file or a pipe.", "Sets must be the same length for a clean one-to-one map (the shorter second set repeats its last character).", "tr works on single bytes: it does not handle multi-byte UTF-8 letters well.",
              "Quote the sets so the shell does not expand [] or *."],
    try_=["Decode a ROT13 string, then encode it again.", "Make a password list upper case.", "Remove all digits from a string.", "Turn a comma-separated line into one item per line."],
    see_also="sed(1) y///, awk(1), iconv(1), dos2unix(1), CyberChef, python str.translate."))

# ============================================================== uniq
GUIDES.append(dict(
    name="uniq", section="1", one_line="report or omit repeated lines",
    plain=["`uniq` finds repeated lines and either removes the repeats, counts them, or shows only the repeated ones. It only compares lines that are next to each other, so you almost always sort first.",
           "uniq -c after sort is the standard way to count how often each thing occurs."],
    when=["Count how many times each IP, user or URL appears.", "Remove duplicate lines from a list.", "Show only the lines that appear once (or more than once)."],
    examples=[("Count each distinct line  (-c)", "awk '{print $1}' access.log | sort | uniq -c", "sort puts equal lines next to each other, then uniq -c prefixes each distinct line with its count."),
              ("Rank by count", "awk '{print $9}' access.log | sort | uniq -c | sort -rn", "Adding sort -rn at the end puts the most common value first. This pipeline is worth memorising."),
              ("Only the duplicates  (-d)", "sort users.txt notes.txt | uniq -d", "-d prints one copy of each line that occurs more than once."),
              ("Only the lines that occur once  (-u)", "awk '{print $1}' access.log | sort | uniq -u", "-u prints lines that never repeat: the rare events, which are often the interesting ones."),
              ("Ignore case  (-i)", "printf 'A\\na\\nB\\n' | sort -f | uniq -i -c", "Treats upper and lower case as the same when comparing."),
              ("Compare only part of the line  (-f, -s, -w)", "uniq -f 3 file", "-f N skips the first N fields, -s N skips N characters and -w N compares at most N characters. Useful for lines that start with a timestamp.")],
    options=[("-c, --count", "Prefix lines with the number of occurrences.", "Counting."),
             ("-d, --repeated", "Print only the duplicated lines, one per group.", "Finding repeats."),
             ("-D, --all-repeated[=METHOD]", "Print all the duplicated lines; METHOD (none, prepend, separate) controls blank-line separators between groups.", "Seeing every copy."),
             ("--group[=METHOD]", "Show all lines, separating groups with an empty line; METHOD is separate, prepend, append or both.", "Visually grouping equal lines."),
             ("-u, --unique", "Print only the lines that are not repeated.", "Rare events."),
             ("-i, --ignore-case", "Ignore case when comparing.", "Case-insensitive counts."),
             ("-f, --skip-fields=N", "Avoid comparing the first N fields.", "Lines that start with a changing timestamp."),
             ("-s, --skip-chars=N", "Avoid comparing the first N characters.", "Fixed-width prefixes."),
             ("-w, --check-chars=N", "Compare no more than N characters of each line.", "Comparing only a prefix."),
             ("-z, --zero-terminated", "Lines end with a NUL byte instead of a newline.", "Output of find -print0."),
             ("--help", "Print a short usage message.", "A quick reminder."),
             ("--version", "Print the version.", "Checking which uniq you have.")],
    mistakes=["Forgetting to sort first: uniq removes only adjacent duplicates, so unsorted input leaves duplicates behind.", "Reading the count wrongly: the number is in front of the line, padded with spaces.", "sort | uniq can be replaced by sort -u when you only want duplicates removed."],
    try_=["Rank the paths requested in access.log.", "List the IPs that appear exactly once.", "Count how many different status codes occur."],
    see_also="sort(1) -u, awk(1), comm(1), wc(1), cut(1)."))

# ============================================================== base64
GUIDES.append(dict(
    name="base64", section="1", one_line="base64 encode or decode data and print to standard output",
    plain=["`base64` converts any data (even binary) into plain text made of letters, digits, + and /, and back. It is an encoding, not encryption: anyone can reverse it with no key.",
           "You meet it everywhere: in HTTP Basic auth headers, tokens (JWT), emails, and challenge hints that end with = or =="],
    when=["Decode a string that looks like base64 (ends with =, only A-Za-z0-9+/).", "Encode a file to paste it into a form or message.", "Decode the parts of a JWT or a Basic auth header."],
    examples=[("Encode text", "echo -n 'hello world' | base64", "-n on echo stops it adding a newline, which would change the result."),
              ("Decode  (-d)", "echo 'aGVsbG8gd29ybGQ=' | base64 -d", "-d decodes. If the output is binary, redirect it to a file instead of the terminal."),
              ("Decode a file", "base64 -d data.b64 > out.bin", "Writes the decoded bytes into out.bin. Then check what it is with file out.bin."),
              ("No line wrapping  (-w 0)", "base64 -w 0 hello | head -c 60; echo", "By default lines are wrapped at 76 characters. -w 0 puts everything on one line, as you need for tokens and headers."),
              ("Ignore junk characters  (-i)", "printf 'aGVs\\nbG8=!!' | base64 -d -i", "-i skips characters that are not in the base64 alphabet, which helps with pasted text that has stray symbols."),
              ("Basic auth header", "echo 'YWxpY2U6c2VjcmV0' | base64 -d", "The part after 'Authorization: Basic ' is user:password in base64, so anyone who sees the request can read it.")],
    options=[("-d, --decode", "Decode data instead of encoding it.", "Reading base64."),
             ("-i, --ignore-garbage", "When decoding, ignore characters that are not part of the base64 alphabet.", "Pasted text with spaces or symbols."),
             ("-w, --wrap=COLS", "Wrap encoded lines after COLS characters (default 76); 0 disables wrapping.", "-w 0 for one line."),
             ("--help", "Print a short usage message.", "A quick reminder."),
             ("--version", "Print the version.", "Checking which base64 you have.")],
    mistakes=["Treating base64 as secrecy: it is only a format.", "Missing = padding makes decoding fail: add = until the length is a multiple of 4.", "URL-safe base64 uses - and _ instead of + and /: translate them first (tr '_-' '/+').", "echo adds a newline: use echo -n or printf."],
    try_=["Encode your name, then decode it.", "Decode a JWT's middle part (add padding if needed).", "Decode a base64 file and identify the result with file."],
    see_also="xxd(1), openssl base64, python3 base64 module, CyberChef (From Base64), basenc(1) for other bases."))

